public class StateListDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
            "StateListReachable",
            "Unreachable state in a `<selector>`",
            "In a selector, only the last child in the state list should omit a "
                    + "state qualifier. If not, all subsequent items in the list will "
                    + "be ignored since the given item will match all.",
            Category.CORRECTNESS, 6, Severity.WARNING,
            new Implementation(StateListDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_SELECTOR);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        NodeList children = element.getChildNodes();
        int count = children.getLength();
        for (int i = 0; i < count; i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element item = (Element) child;
                boolean hasState = false;
                NamedNodeMap attributes = item.getAttributes();
                if (attributes != null) {
                    for (int j = 0, m = attributes.getLength(); j < m; j++) {
                        Attr attr = (Attr) attributes.item(j);
                        String name = attr.getLocalName();
                        if (name != null && name.startsWith(STATE_PREFIX)) {
                            hasState = true;
                            break;
                        }
                    }
                }
                if (!hasState) {
                    if (i < count - 1) {
                        // Check if there are any subsequent element nodes
                        boolean hasSubsequentElements = false;
                        for (int k = i + 1; k < count; k++) {
                            if (children.item(k).getNodeType() == Node.ELEMENT_NODE) {
                                hasSubsequentElements = true;
                                break;
                            }
                        }
                        if (hasSubsequentElements) {
                            context.report(ISSUE, context.getLocation(item),
                                    "This item matches all states and is not last, so subsequent items will be ignored");
                        }
                    }
                }
            }
        }
    }
}
